19	string WorkspaceFile(string relative)
20	{
21	    if (Path.IsPathRooted(relative)) throw new ArgumentException("Fixture report paths must be relative.");
22	    var root = Path.GetFullPath(Environment.CurrentDirectory) + Path.DirectorySeparatorChar;
23	    var absolute = Path.GetFullPath(relative, root);
24	    if (!absolute.StartsWith(root, OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal))
25	        throw new ArgumentException("Fixture output must remain within its synthetic workspace.");
26	    return absolute;
27	}
